macro_rules! AsciiWordBoundIter {
    () => {
        # [doc = " ASCII‑fast‑path word‑boundary iterator for strings that contain only ASCII characters."] # [doc = ""] # [doc = " Since we handle only ASCII characters, we can use a much simpler set of"] # [doc = " word break values than the full Unicode algorithm."] # [doc = " https://www.unicode.org/reports/tr29/#Table_Word_Break_Property_Values"] # [doc = ""] # [doc = " | Word_Break value | ASCII code points that belong to it                             |"] # [doc = " | -----------------| --------------------------------------------------------------- |"] # [doc = " | CR               | U+000D\u{a0}(CR)                                                     |"] # [doc = " | LF               | U+000A\u{a0}(LF)                                                     |"] # [doc = " | Newline          | U+000B\u{a0}(VT),\u{202f}U+000C\u{a0}(FF)                                        |"] # [doc = " | Single_Quote     | U+0027\u{a0}(')                                                      |"] # [doc = " | Double_Quote     | U+0022\u{a0}(\")                                                      |"] # [doc = " | MidNumLet        | U+002E\u{a0}(.)\u{a0}FULL\u{a0}STOP                                            |"] # [doc = " | MidLetter        | U+003A\u{a0}(:)\u{a0}COLON                                                |"] # [doc = " | MidNum           | U+002C\u{a0}(,),\u{202f}U+003B\u{a0}(;)                                          |"] # [doc = " | Numeric          | U+0030\u{202f}–\u{202f}U+0039\u{a0}(0\u{202f}…\u{202f}9)                                         |"] # [doc = " | ALetter          | U+0041\u{202f}–\u{202f}U+005A\u{a0}(A\u{202f}…\u{202f}Z),\u{202f}U+0061\u{202f}–\u{202f}U+007A\u{a0}(a\u{202f}…\u{202f}z)                |"] # [doc = " | ExtendNumLet     | U+005F\u{a0}(_)\u{a0}underscore                                           |"] # [doc = " | WSegSpace        | U+0020\u{a0}(SPACE)                                                  |"] # [doc = ""] # [doc = " The macro MidNumLetQ boils down to: U+002E\u{a0}(.)\u{a0}FULL\u{a0}STOP and U+0027\u{a0}(')"] # [doc = " AHLetter is the same as ALetter, so we don't need to distinguish it."] # [doc = ""] # [doc = " Any other single ASCII byte is its own boundary (the default WB999)."] # [derive (Debug)] struct AsciiWordBoundIter < 'a > { rest : & 'a str , offset : usize , }
    };
}

AsciiWordBoundIter!();